with OUT.open("w", encoding="utf-8") as fh:
    for f in F:
        slug = "-".join(f["title"].lower().split()[:6]).replace("/", "-")
        fp = hashlib.sha1(f"{f['category']}|{f['path']}|{f['symbol']}|{slug}".encode()).hexdigest()[:12]
        rec = {"id": f["id"], "fingerprint": fp, "commit": COMMIT, "severity": f["severity"],
               "confidence": f["confidence"], "category": f["category"], "title": f["title"],
               "location": f["location"], "trigger": f["trigger"], "impact": f["impact"],
               "reachability": f["reachability"], "platform": f["platform"], "evidence": f["evidence"],
               "falsification": f["falsification"], "fix": f["fix"], "effort": f["effort"],
               "verifier": f["verifier"]}
        fh.write(json.dumps(rec, ensure_ascii=False) + "\n")
print("wrote", OUT, len(F), "findings")
